import { pick, sumBy } from 'es-toolkit';
import { truncate } from 'es-toolkit/compat';

export interface Row {
  id: number;
  name: string;
  age: number;
}

export type Config = Record<string, unknown>;

export function publicFields(row: Row): Pick<Row, 'id' | 'name'> {
  return pick(row, ['id', 'name']);
}

export function totalAge(rows: Row[]): number {
  return sumBy(rows, (row) => row.age);
}

export function preview(text: string): string {
  return truncate(text, { length: 24 });
}
EOF
npm run size -- out/module.ts 2>&1 | tail -2
sed -e "s#from 'es-toolkit';#from 'es-toolkit/compat';#; /^import { truncate/d; s#import { pick, sumBy }#import { pick, sumBy, truncate }#; s#(row) => row.age#'age'#" out/module.ts > out/c.ts
npm run size -- out/c.ts 2>&1 | tail -1
npx tsc --noEmit --strict --module esnext --moduleResolution bundler --target es2022 out/module.ts && echo ok

